input.sparql:
SELECT ?work ?workLabel ?lcsh ?fast ?year WHERE {
  ?work wdt:P921 ?subject .
  ?subject wdt:P279* wd:Q17167 .
  VALUES ?economic_concept { wd:Q8134 wd:Q39809 wd:Q184574 wd:Q4406 wd:Q39072 }
  ?work wdt:P921 ?economic_concept .
  OPTIONAL { ?work wdt:P244 ?lcsh }
  OPTIONAL { ?work wdt:P2163 ?fast }
  OPTIONAL { ?work wdt:P577 ?pub_date . BIND(YEAR(?pub_date) AS ?year) }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 20

SELECT ?work ?workLabel ?author ?authorLabel ?year WHERE {
  VALUES ?economic { wd:Q8134 wd:Q39809 wd:Q184574 }
  VALUES ?roman { wd:Q17167 wd:Q2277 wd:Q1747689 }
  ?work wdt:P921 ?economic .
  ?work wdt:P921 ?roman .
  OPTIONAL { ?work wdt:P50 ?author }
  OPTIONAL { ?work wdt:P577 ?pub_date . BIND(YEAR(?pub_date) AS ?year) }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 15

SELECT ?work ?workLabel ?author ?authorLabel WHERE {
  VALUES ?subject { wd:Q17167 wd:Q1747689 }
  ?work wdt:P921 ?subject .
  ?work wdt:P244 ?lcsh .
  ?author wdt:P50 ?work .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 10
